2	package org.springframework.samples.petclinic.util;
3	
4	import java.util.Map;
5	
6	/**
7	 * Derives an owner's 'locality' (canonical region) from the postcode and city.
8	 *
9	 * <p>The region is resolved by the postcode range first
10	 * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), and only
11	 * falls back to the fixed city-to-region table ({@code Sydney -> NSW},
12	 * {@code Melbourne -> VIC}, {@code Brisbane -> QLD}) when the postcode is absent or
13	 * in no known range. Preferring the postcode returns the same region for known cities
14	 * but disambiguates cities that share a name.
15	 *
16	 * <p>A city not covered by either lookup (or a {@code null} city with no matching
17	 * postcode) resolves to {@code 'UNKNOWN'}.
18	 */
19	public final class LocalityResolver {
20	
21	    /** City -> canonical region. Cities not listed derive locality 'UNKNOWN'. */
22	    private static final Map<String, String> CITY_REGION = Map.of(
23	        "Sydney", "NSW",
24	        "Melbourne", "VIC",
25	        "Brisbane", "QLD");
26	
27	    /**
28	     * Region -> inclusive 4-digit postcode range {low, high}. This is the single source of
29	     * truth for the region&harr;postcode relationship, read both here (postcode -> region)
30	     * and by {@link PostcodeValidator} (region -> range, via {@link #postcodeRange}).
31	     */
32	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
33	        "NSW", new int[] {2000, 2099},
34	        "VIC", new int[] {3000, 3099},
35	        "QLD", new int[] {4000, 4099});
36	
37	    /**
38	     * Region -> IANA timezone name. The fixed region-to-timezone table; regions not listed
39	     * (e.g. {@code 'UNKNOWN'}) have no mapped timezone.
40	     */
41	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
42	        "NSW", "Australia/Sydney",
43	        "VIC", "Australia/Melbourne",
44	        "QLD", "Australia/Brisbane");
45	
46	    /** Locality returned when neither the postcode nor the city resolves a region. */
47	    private static final String UNKNOWN = "UNKNOWN";
48	
49	    private LocalityResolver() {
50	    }
51	
52	    /**
53	     * Resolve the canonical region for a city, using the city-to-region table only.
54	     *
55	     * @param city the owner's city (any value)
56	     * @return the canonical region string, or {@code 'UNKNOWN'} when the city is not
57	     *         in the table.
58	     */
59	    public static String resolve(String city) {
60	        return CITY_REGION.getOrDefault(city, UNKNOWN);
61	    }
62	
63	    /**
64	     * Resolve the canonical region, preferring the postcode over the city. The region
65	     * is looked up by postcode range first; when the postcode is absent or in no known
66	     * range, the city-to-region table is used as a fallback.
67	     *
68	     * @param city     the owner's city (used as a fallback)
69	     * @param postcode the owner's postcode, or {@code null} when none was given
70	     * @return the canonical region string, or {@code 'UNKNOWN'} when neither lookup
71	     *         resolves a region.
72	     */
73	    public static String resolve(String city, String postcode) {
74	        String fromPostcode = resolveByPostcode(postcode);
75	        return fromPostcode != null ? fromPostcode : resolve(city);
76	    }
77	
78	    /**
79	     * Whether the given locality is a known canonical region (one with a reserved postcode
80	     * range: {@code NSW}, {@code VIC} or {@code QLD}), as opposed to the {@code 'UNKNOWN'}
81	     * sentinel or any other value. Reads the single-sourced {@code REGION_POSTCODES} table so
82	     * region-membership stays defined by the one place that owns the region knowledge.
83	     *
84	     * @param region a locality/region string (e.g. {@code 'NSW'} or {@code 'UNKNOWN'})
85	     * @return {@code true} when the region has a reserved postcode range
86	     */
87	    public static boolean isKnownRegion(String region) {
88	        return REGION_POSTCODES.containsKey(region);
89	    }
90	
91	    /**
92	     * The IANA timezone name for a region, via the fixed region-to-timezone table
93	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
94	     * {@code QLD -> Australia/Brisbane}).
95	     *
96	     * @param region a canonical region string (e.g. {@code 'NSW'})
97	     * @return the IANA timezone name, or {@code null} when the region has no mapped timezone
98	     */
99	    public static String timezone(String region) {
100	        return REGION_TIMEZONE.get(region);
101	    }
102	
103	    /**
104	     * The inclusive 4-digit postcode range {@code {low, high}} reserved for a region, or
105	     * {@code null} when the region has no reserved range. Exposes the single-sourced
106	     * {@code REGION_POSTCODES} table for {@link PostcodeValidator}.
107	     *
108	     * @param region a canonical region string (e.g. {@code 'NSW'})
109	     * @return a defensive copy of the {@code {low, high}} range, or {@code null} if none
110	     */
111	    static int[] postcodeRange(String region) {
112	        int[] range = REGION_POSTCODES.get(region);
113	        return range == null ? null : range.clone();
114	    }
115	
116	    /** Region whose range contains the postcode, or {@code null} if none (or unparseable). */
117	    private static String resolveByPostcode(String postcode) {
118	        if (postcode == null) {
119	            return null;
120	        }
121	        int value;
122	        try {
123	            value = Integer.parseInt(postcode.trim());
124	        }
125	        catch (NumberFormatException e) {
126	            return null;
127	        }
128	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
129	            int[] range = entry.getValue();
130	            if (value >= range[0] && value <= range[1]) {
131	                return entry.getKey();
132	            }
133	        }
134	        return null;
135	    }
136	}
