138	package org.springframework.samples.petclinic.util;
139	
140	import java.nio.charset.StandardCharsets;
141	import java.security.MessageDigest;
142	import java.security.NoSuchAlgorithmException;
143	
144	/**
145	 * Computes a hexadecimal SHA-256 digest of a string, either as a truncated upper-case prefix
146	 * ({@link #upperHexPrefix}) or as the full 64-character lower-case digest ({@link #lowerHex}).
147	 * Used wherever a stable hash is needed over owner data: the hash segment of the customer code and
148	 * the shared household identifier use the prefix form, while the owner identity key uses the full
149	 * lower-case form.
150	 */
151	public final class Sha256Hex {
152	
153	    private Sha256Hex() {
154	    }
155	
156	    /**
157	     * The first {@code chars} upper-case hexadecimal characters of the SHA-256 digest of the UTF-8
158	     * bytes of {@code value} (e.g. {@code chars = 8} returns the first 4 bytes as 8 hex characters).
159	     *
160	     * @param value the string to hash
161	     * @param chars the number of leading hexadecimal characters to return (0 to 64)
162	     * @return the truncated upper-case hexadecimal digest
163	     */
164	    public static String upperHexPrefix(String value, int chars) {
165	        try {
166	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
167	            StringBuilder sb = new StringBuilder(chars);
168	            for (int i = 0; i < digest.length && sb.length() < chars; i++) {
169	                sb.append(String.format("%02X", digest[i]));
170	            }
171	            return sb.substring(0, chars);
172	        } catch (NoSuchAlgorithmException ex) {
173	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
174	        }
175	    }
176	
177	    /**
178	     * The full 64-character lower-case hexadecimal SHA-256 digest of the UTF-8 bytes of
179	     * {@code value}. Used for the owner identity key, which is compared in its entirety.
180	     *
181	     * @param value the string to hash
182	     * @return the 64-character lower-case hexadecimal digest
183	     */
184	    public static String lowerHex(String value) {
185	        try {
186	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
187	            StringBuilder sb = new StringBuilder(digest.length * 2);
188	            for (byte b : digest) {
189	                sb.append(String.format("%02x", b));
190	            }
191	            return sb.toString();
192	        } catch (NoSuchAlgorithmException ex) {
193	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
194	        }
195	    }
196	}
