218	/**
219	 * Immutable structured audit event emitted once per owner create, alongside the
220	 * human-readable audit line.
221	 *
222	 * <p>The {@code memberId} component carries the owner's <em>current primary
223	 * identifier</em>, the unified {@link Owner#getMemberId() memberId}, sourced through
224	 * {@link #primaryIdentifier(Owner)} so the single place to change it lives there, not
225	 * at the call site.
226	 *
227	 * <p>Being a {@code record} the event is immutable once published.
228	 */
229	public record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
230	        Integer membershipLevel, String event) {
231	
232	    /** The fixed {@code event} discriminator for an owner-created event. */
233	    public static final String OWNER_CREATED = "OWNER_CREATED";
234	
235	    /**
236	     * Build the event for a freshly created {@code owner}, stamping it with the given
237	     * monotonically increasing {@code seq} and {@code membershipLevel}.
238	     *
239	     * <p>{@code ownerId} and the primary identifier are read straight from the owner, but
240	     * {@code membershipLevel} is supplied pre-derived by the caller on purpose: deriving it
241	     * requires {@code OwnerMapper} (the {@code mapper} package), and this {@code audit}
242	     * package deliberately does not depend on it. Do not "simplify" this by pulling the
243	     * mapper in here.
244	     */
245	    public static OwnerCreatedEvent of(long seq, Owner owner, Integer membershipLevel) {
246	        return new OwnerCreatedEvent(seq, owner.getId(), primaryIdentifier(owner),
247	                membershipLevel, OWNER_CREATED);
248	    }
249	
250	    /**
251	     * The owner's current primary identifier, the unified memberId. Change this one expression
252	     * to re-source every emitted event's primary identifier.
253	     */
254	    private static String primaryIdentifier(Owner owner) {
255	        return owner.getMemberId();
256	    }
257	}
