519	        }
520	        if (owner.getRegistrationDate() != null
521	                && FiscalYear.startYear(LocalDate.now()) - FiscalYear.startYear(owner.getRegistrationDate()) >= 1) {
522	            points += 3;
523	        }
524	        return points;
