    @Named("formatFiscalYear")
    default String formatFiscalYear(Owner owner) {
        if (owner == null) {
            return null;
        }
        String fy = memberIdFiscalYear(owner.getMemberId());
        if (fy != null) {
            return "FY" + fy;
        }
        if (owner.getRegistrationDate() == null) {
            return null;
