442	    /**
443	     * Resolve the id of an existing owner that the given (not yet persisted) owner is a <em>possible</em>
444	     * duplicate of, or {@code null} when there is none. A possible duplicate has a <em>different</em>
445	     * identity key from the existing owner (so it is not a hard duplicate) yet shares the Soundex code
446	     * of its last name and the same postcode, so it is worth flagging as a soft match. When several
447	     * existing owners match, the one with the lowest id is returned so the result is deterministic.
448	     * Computed once, at creation, to drive the read-only {@code possibleDuplicate}/
449	     * {@code possibleDuplicateOf} fields.
450	     */
451	    private Integer findPossibleDuplicateOf(Owner owner) {
452	        String identityKey = owner.getIdentityKey();
453	        String lastNameSoundex = Soundex.encode(owner.getLastName());
454	        String postcode = owner.getPostcode();
455	        return ownerRepository.findAll().stream()
456	            .filter(existing -> existing != owner && existing.getId() != null)
457	            .filter(existing -> !existing.isDeleted())
458	            .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
459	            .filter(existing -> lastNameSoundex.equals(Soundex.encode(existing.getLastName())))
460	            .filter(existing -> Objects.equals(postcode, existing.getPostcode()))
461	            .map(Owner::getId)
462	            .min(Integer::compareTo)
463	            .orElse(null);
464	    }
