466	    /**
467	     * Compute the membership-level ceiling for a new owner, as required by the level-cap rule: a new
468	     * owner's {@code membershipLevel} cannot exceed one above the current maximum membership level
469	     * among its household members (existing owners sharing the same {@code householdId}, excluding
470	     * soft-deleted ones and the owner itself). Returns one above that maximum, or {@code null} when
471	     * the owner has no household id or no existing household member, in which case no cap applies.
472	     *
473	     * <p>Each existing member's level is read through {@link OwnerMapper#formatMembershipLevel},
474	     * after decorating the members with their current household member counts, so the maximum
475	     * reflects the same effective (already-capped) level the API returns for those members.
476	     */
477	    private Integer computeMembershipLevelCap(Owner newOwner) {
478	        String householdId = newOwner.getHouseholdId();
479	        if (householdId == null) {
480	            return null;
481	        }
482	        List<Owner> members = ownerRepository.findAll().stream()
483	            .filter(existing -> existing != newOwner && existing.getId() != null)
484	            .filter(existing -> !existing.isDeleted())
485	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
486	            .collect(Collectors.toList());
487	        if (members.isEmpty()) {
488	            return null;
489	        }
490	        decorateWithHouseholdMemberCount(members, members);
491	        int maxLevel = members.stream()
492	            .mapToInt(member -> ownerMapper.formatMembershipLevel(member))
493	            .max()
494	            .getAsInt();
495	        return maxLevel + 1;
496	    }
