505	    /**
506	     * Normalizes a household field (the last name) for the {@link #householdIdFor household id}
507	     * hash by trimming, collapsing runs of whitespace to a single space and lower-casing, so
508	     * differently cased or spaced but equivalent values yield the same household id.
509	     */
510	    private static String normalizeHouseholdValue(String value) {
511	        if (value == null) {
512	            return "";
513	        }
514	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
515	    }
