517	    /**
518	     * Populate each given owner's transient {@code householdMemberCount} with the current number of
519	     * owners that share its {@code householdId}. Owners without a household id are left at a count
520	     * of zero.
521	     *
522	     * <p>The household sizes are computed in a single pass over the owner table regardless of how
523	     * many owners are being decorated, so decorating a whole page does not re-scan per element.
524	     */
525	    private <T> T decorateWithHouseholdMemberCount(T result, Collection<Owner> owners) {
526	        if (!owners.isEmpty()) {
527	            Map<String, Long> sizeByHousehold = ownerRepository.findAll().stream()
528	                .filter(owner -> owner.getHouseholdId() != null)
529	                .collect(Collectors.groupingBy(Owner::getHouseholdId, Collectors.counting()));

