17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.slf4j.Logger;
23	import org.slf4j.LoggerFactory;
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.audit.OwnerAuditEventPublisher;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.samples.petclinic.service.IdempotencyKeyRegistry;
43	import org.springframework.samples.petclinic.util.AddressValidator;
44	import org.springframework.samples.petclinic.util.CityCapacityException;
45	import org.springframework.samples.petclinic.util.DisposableEmailValidator;
46	import org.springframework.samples.petclinic.util.DuplicateOwnerException;
47	import org.springframework.samples.petclinic.util.PostcodeValidator;
48	import org.springframework.samples.petclinic.util.RegistrationDateValidator;
49	import org.springframework.samples.petclinic.util.RegistrationRateLimitException;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
68	
69	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
70	
71	    private final ClinicService clinicService;
72	
73	    private final OwnerMapper ownerMapper;
74	
75	    private final PetMapper petMapper;
76	
77	    private final VisitMapper visitMapper;
78	
79	    private final IdempotencyKeyRegistry idempotencyKeyRegistry;
80	
81	    private final OwnerAuditEventPublisher auditEventPublisher;
82	
83	    public OwnerRestControllerV1(ClinicService clinicService,
84	                                 OwnerMapper ownerMapper,
85	                                 PetMapper petMapper,
86	                                 VisitMapper visitMapper,
87	                                 IdempotencyKeyRegistry idempotencyKeyRegistry,
88	                                 OwnerAuditEventPublisher auditEventPublisher) {
89	        this.clinicService = clinicService;
90	        this.ownerMapper = ownerMapper;
91	        this.petMapper = petMapper;
92	        this.visitMapper = visitMapper;
93	        this.idempotencyKeyRegistry = idempotencyKeyRegistry;
94	        this.auditEventPublisher = auditEventPublisher;
95	    }
96	
97	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
98	    @Override
99	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
100	        Collection<Owner> owners;
101	        if (lastName != null) {
102	            owners = this.clinicService.findOwnerByLastName(lastName);
103	        } else {
104	            owners = this.clinicService.findAllOwners();
105	        }
106	        if (owners.isEmpty()) {
107	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
108	        }
109	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
110	    }
111	
112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
115	        Owner owner = this.clinicService.findOwnerById(ownerId);
116	        if (owner == null) {
117	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
118	        }
119	        return new ResponseEntity<>(toOwnerDtoWithWarning(owner), HttpStatus.OK);
120	    }
121	
122	    /** Map an owner to its DTO, setting the read-only {@code bulkSignupWarning},
123	     *  {@code capacityWarning} and {@code riskFlag} flags the same way for every owner response. */
124	    private OwnerDto toOwnerDtoWithWarning(Owner owner) {
125	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
126	        ownerDto.setBulkSignupWarning(this.clinicService.isBulkSignupDay());
127	        ownerDto.setCapacityWarning(this.clinicService.isCityApproachingCapacity(owner.getCity()));
128	        ownerDto.setRiskFlag(isRiskFlag(owner));
129	        return ownerDto;
130	    }
131	
132	    /** Compute the read-only {@code riskFlag}: true when the owner is a possible duplicate, its
133	     *  email domain is disposable-adjacent, or its city is over its soft capacity. */
134	    private boolean isRiskFlag(Owner owner) {
135	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
136	            || DisposableEmailValidator.isDisposableAdjacent(owner.getEmail())
137	            || this.clinicService.isCityOverSoftCapacity(owner.getCity());
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
143	        // A create retried with an already-seen idempotency key returns the originally created
144	        // owner with 200, rather than creating a duplicate.
145	        Integer existingId = this.idempotencyKeyRegistry.findOwnerId(idempotencyKey).orElse(null);
146	        if (existingId != null) {
147	            Owner existing = this.clinicService.findOwnerById(existingId);
148	            if (existing != null) {
149	                return new ResponseEntity<>(toOwnerDtoWithWarning(existing), HttpStatus.OK);
150	            }
151	        }
152	        HttpHeaders headers = new HttpHeaders();
153	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
154	        AddressValidator.validate(owner.getAddress());
155	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
156	        DisposableEmailValidator.validate(owner.getEmail());
157	        RegistrationDateValidator.validate(owner.getRegistrationDate());
158	        if (this.clinicService.isDailyRegistrationAtCapacity()) {
159	            throw new RegistrationRateLimitException();
160	        }
161	        // The household id is deterministic from (lastName, postcode), so owners sharing a last name
162	        // and postcode are automatically the same household. It no longer gates duplicate detection
163	        // (that is the identity key alone) but still drives household-derived fields.
164	        owner.setHouseholdId(this.clinicService.householdIdFor(owner.getLastName(), owner.getPostcode()));
165	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
166	        // Duplicate detection is the single identity key: reject only when the new owner's whole
167	        // identity key (SHA-256 over normalizedTelephone|lowerEmail|soundex(lastName)) matches an
168	        // existing, non-deleted owner's. Two owners with the same last name and postcode but different
169	        // telephones have distinct keys and are created as a soft match rather than rejected.
170	        if (this.clinicService.isIdentityKeyInUse(owner)) {
171	            throw new DuplicateOwnerException();
172	        }
173	        if (this.clinicService.isCityAtCapacity(owner.getCity())) {
174	            throw new CityCapacityException();
175	        }
176	        this.clinicService.saveOwner(owner, sharesHousehold);
177	        this.idempotencyKeyRegistry.remember(idempotencyKey, owner.getId());
178	        AUDIT.info("owner created: id={} memberId={} registrationDate={} membershipLevel={}",
179	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
180	            ownerMapper.formatMembershipLevel(owner));
181	        this.auditEventPublisher.ownerCreated(owner, ownerMapper.formatMembershipLevel(owner));
182	        // Enqueue a welcome notification for the newly created owner.
183	        NOTIFY.info("welcome notification: owner id={} memberId={}", owner.getId(), owner.getMemberId());
184	        OwnerDto ownerDto = toOwnerDtoWithWarning(owner);
185	        headers.setLocation(UriComponentsBuilder.newInstance()
186	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
187	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
188	    }
189	
190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Override
192	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
193	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
194	        if (currentOwner == null) {
195	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
196	        }
197	        PostcodeValidator.validate(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
198	        DisposableEmailValidator.validate(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
199	        ownerMapper.applyAddressFields(ownerFieldsDto, currentOwner);
200	        AddressValidator.validate(currentOwner.getAddress());
201	        currentOwner.setCity(ownerFieldsDto.getCity());
202	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
203	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
204	        currentOwner.setLastName(ownerFieldsDto.getLastName());
205	        currentOwner.setTitle(ownerMapper.mapTitle(ownerFieldsDto.getTitle()));
206	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
207	        currentOwner.setEmail(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
208	        this.clinicService.saveOwner(currentOwner);
209	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
210	    }
211	
212	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
213	    @Transactional
214	    @Override
215	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
216	        Owner owner = this.clinicService.findOwnerById(ownerId);
217	        if (owner == null) {
218	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
219	        }
220	        this.clinicService.deleteOwner(owner);
