package org.springframework.samples.petclinic.rest.controller.v1;

import java.util.Collection;
import java.util.List;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.audit.OwnerAuditEventPublisher;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.mapper.PetMapper;
import org.springframework.samples.petclinic.mapper.VisitMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.model.Pet;
import org.springframework.samples.petclinic.model.Visit;
import org.springframework.samples.petclinic.rest.api.OwnersApi;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.PetDto;
import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
import org.springframework.samples.petclinic.rest.dto.VisitDto;
import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
import org.springframework.samples.petclinic.service.ClinicService;
import org.springframework.samples.petclinic.service.IdempotencyKeyRegistry;
import org.springframework.samples.petclinic.util.AddressValidator;
import org.springframework.samples.petclinic.util.CityCapacityException;
import org.springframework.samples.petclinic.util.DisposableEmailValidator;
import org.springframework.samples.petclinic.util.DuplicateOwnerException;
import org.springframework.samples.petclinic.util.PostcodeValidator;
import org.springframework.samples.petclinic.util.RegistrationDateValidator;
import org.springframework.samples.petclinic.util.RegistrationRateLimitException;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.CrossOrigin;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.util.UriComponentsBuilder;

import jakarta.transaction.Transactional;

/**
 * @author Vitaliy Fedoriv
 */

@RestController
@CrossOrigin(exposedHeaders = "errors, content-type")
@RequestMapping("/api")
public class OwnerRestControllerV1 implements OwnersApi {

    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");

    private final ClinicService clinicService;

    private final OwnerMapper ownerMapper;

    private final PetMapper petMapper;

    private final VisitMapper visitMapper;

    private final IdempotencyKeyRegistry idempotencyKeyRegistry;

    private final OwnerAuditEventPublisher auditEventPublisher;

    public OwnerRestControllerV1(ClinicService clinicService,
                                 OwnerMapper ownerMapper,
                                 PetMapper petMapper,
                                 VisitMapper visitMapper,
                                 IdempotencyKeyRegistry idempotencyKeyRegistry,
                                 OwnerAuditEventPublisher auditEventPublisher) {
        this.clinicService = clinicService;
        this.ownerMapper = ownerMapper;
        this.petMapper = petMapper;
        this.visitMapper = visitMapper;
        this.idempotencyKeyRegistry = idempotencyKeyRegistry;
        this.auditEventPublisher = auditEventPublisher;
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
        Collection<Owner> owners;
        if (lastName != null) {
            owners = this.clinicService.findOwnerByLastName(lastName);
        } else {
            owners = this.clinicService.findAllOwners();
        }
        if (owners.isEmpty()) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(toOwnerDtoWithWarning(owner), HttpStatus.OK);
    }

    /** Map an owner to its DTO, setting the read-only {@code bulkSignupWarning},
     *  {@code capacityWarning} and {@code riskFlag} flags the same way for every owner response. */
    private OwnerDto toOwnerDtoWithWarning(Owner owner) {
        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
        ownerDto.setBulkSignupWarning(this.clinicService.isBulkSignupDay());
        ownerDto.setCapacityWarning(this.clinicService.isCityApproachingCapacity(owner.getCity()));
        ownerDto.setRiskFlag(isRiskFlag(owner));
        return ownerDto;
    }

    /** Compute the read-only {@code riskFlag}: true when the owner is a possible duplicate, its
     *  email domain is disposable-adjacent, or its city is over its soft capacity. */
    private boolean isRiskFlag(Owner owner) {
        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
            || DisposableEmailValidator.isDisposableAdjacent(owner.getEmail())
            || this.clinicService.isCityOverSoftCapacity(owner.getCity());
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
        // A create retried with an already-seen idempotency key returns the originally created
        // owner with 200, rather than creating a duplicate.
        Integer existingId = this.idempotencyKeyRegistry.findOwnerId(idempotencyKey).orElse(null);
        if (existingId != null) {
            Owner existing = this.clinicService.findOwnerById(existingId);
            if (existing != null) {
                return new ResponseEntity<>(toOwnerDtoWithWarning(existing), HttpStatus.OK);
            }
        }
        HttpHeaders headers = new HttpHeaders();
        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
        AddressValidator.validate(owner.getAddress());
        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
        DisposableEmailValidator.validate(owner.getEmail());
        RegistrationDateValidator.validate(owner.getRegistrationDate());
        if (this.clinicService.isDailyRegistrationAtCapacity()) {
            throw new RegistrationRateLimitException();
        }
        // The household id is deterministic from (lastName, postcode), so owners sharing a last name
        // and postcode are automatically the same household. It no longer gates duplicate detection
        // (that is the identity key alone) but still drives household-derived fields.
        owner.setHouseholdId(this.clinicService.householdIdFor(owner.getLastName(), owner.getPostcode()));
        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
        // Duplicate detection is the single identity key: reject only when the new owner's whole
        // identity key (SHA-256 over normalizedTelephone|lowerEmail|soundex(lastName)) matches an
        // existing, non-deleted owner's. Two owners with the same last name and postcode but different
        // telephones have distinct keys and are created as a soft match rather than rejected.
        if (this.clinicService.isIdentityKeyInUse(owner)) {
            throw new DuplicateOwnerException();
        }
        if (this.clinicService.isCityAtCapacity(owner.getCity())) {
            throw new CityCapacityException();
        }
        this.clinicService.saveOwner(owner, sharesHousehold);
        this.idempotencyKeyRegistry.remember(idempotencyKey, owner.getId());
        AUDIT.info("owner created: id={} memberId={} registrationDate={} membershipLevel={}",
            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
            ownerMapper.formatMembershipLevel(owner));
        this.auditEventPublisher.ownerCreated(owner, ownerMapper.formatMembershipLevel(owner));
        // Enqueue a welcome notification for the newly created owner.
        NOTIFY.info("welcome notification: owner id={} memberId={}", owner.getId(), owner.getMemberId());
        OwnerDto ownerDto = toOwnerDtoWithWarning(owner);
        headers.setLocation(UriComponentsBuilder.newInstance()
            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        PostcodeValidator.validate(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
        DisposableEmailValidator.validate(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
        ownerMapper.applyAddressFields(ownerFieldsDto, currentOwner);
        AddressValidator.validate(currentOwner.getAddress());
        currentOwner.setCity(ownerFieldsDto.getCity());
        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
        currentOwner.setLastName(ownerFieldsDto.getLastName());
        currentOwner.setTitle(ownerMapper.mapTitle(ownerFieldsDto.getTitle()));
        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
        currentOwner.setEmail(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
        this.clinicService.saveOwner(currentOwner);
        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Transactional
    @Override
    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        this.clinicService.deleteOwner(owner);
        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        HttpHeaders headers = new HttpHeaders();
        Pet pet = petMapper.toPet(petFieldsDto);
        owner.setId(ownerId);
        pet.setOwner(owner);
        pet.getType().setName(null);
        this.clinicService.savePet(pet);
        PetDto petDto = petMapper.toPetDto(pet);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
            .buildAndExpand(pet.getId()).toUri());
        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner != null) {
            Pet currentPet = this.clinicService.findPetById(petId);
            if (currentPet != null) {
                currentPet.setBirthDate(petFieldsDto.getBirthDate());
                currentPet.setName(petFieldsDto.getName());
                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
                this.clinicService.savePet(currentPet);
                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
        HttpHeaders headers = new HttpHeaders();
        Visit visit = visitMapper.toVisit(visitFieldsDto);
        Pet pet = new Pet();
        pet.setId(petId);
        visit.setPet(pet);
        this.clinicService.saveVisit(visit);
        VisitDto visitDto = visitMapper.toVisitDto(visit);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
            .buildAndExpand(visit.getId()).toUri());
        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
    }


    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner != null) {
            Pet pet = owner.getPet(petId);
            if (pet != null) {
                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }
}

